        case "updateHireVehicleOdometerDifferenceVehicleManagement":
            $moduleId = $_POST["moduleId"];
            $hireVehicleRequestId = $_POST["hireVehicleRequestId"];
            $processStatusId = $_POST["processStatusId"];
            $clientRequestId = $_POST["clientRequestId"];
            $clientServiceId = $_POST["clientServiceId"];
            $odometerEnding = $_POST["odometerEnding"];
            $fuelTankEnding = $_POST["fuelTankEnding"];
            $vehicleCurrentStatusId = $_POST["vehicleCurrentStatusId"];
            $vehicleId = $_POST["vehicleId"];

            $odometerEndingPattern = "/^[0-9]+$/";  
            $fuelTankEndingPattern = "/^[0-9]+$/";  
            try {
                if (
                    $odometerEnding != "" & $fuelTankEnding != ""
                ) {
                    if (
                        preg_match($odometerEndingPattern, $odometerEnding) & preg_match($fuelTankEndingPattern, $fuelTankEnding)
                    ) { 
                        $getSpecificHireVehicleRequestByHireVehicleRequestIdResult = $modelObj->getSpecificHireVehicleRequestByHireVehicleRequestId($hireVehicleRequestId);
