                        $fuelTankStarting = $getSpecificHireVehicleRequestByHireVehicleRequestIdRow["fuelTankStarting"];

                        if ($odometerEnding > $odometerStarting & $fuelTankEnding < $fuelTankStarting) {
                            $odoMeterDifference = $odometerEnding - $odometerStarting;

                            $fuelConsumption1 = $fuelTankStarting - $fuelTankEnding;
                            $fuelConsumption = $odoMeterDifference / $fuelConsumption1;
                            $modelObj->updateVehicleDashboardFuelTankAvaialabilityOdometerFuelConsumption($fuelTankEnding, $odometerEnding, $fuelConsumption, $vehicleId);

                            $modelObj->updateHireVehicleRequestEndingOdometeFuelTankAvailability($hireVehicleRequestId, $odometerEnding, $fuelTankEnding);
                            $modelObj->updateClientRequestForHireVehicleTaskCompleted($clientRequestId, $processStatusId);
                            $modelObj->vehicleCurrentStatusIdChangeing($vehicleId, $vehicleCurrentStatusId);
                            $msg = "Hire Vehicle Task is Completed!";
