            $vehicleColorId = $_POST["vehicleColorId"];
            $classOfVehicleId = $_POST["classOfVehicleId"];

            $vehicleRegistrationNumber = $_POST["vehicleRegistrationNumber"];
            $vehicleImage = $_FILES["vehicleImage"];

            $moduleId = $_POST["moduleId"];

            $vehicleRegistrationNumberPattern = "/^[A-Z]{1,2}\s[A-Z]{1,3}\-[0-9]{4}(?<! 0{4})$/";

            $vehicleImageEdit = "";  
            if($vehicleImage["name"] != ""){
                $vehicleImageEdit = $vehicleImage["name"];
                $path = "../images/vehicle_images/".$vehicleImageEdit;
                move_uploaded_file($vehicleImage["tmp_name"], $path);                                       
            }

            $allvehicleRegistrationNumbers = array();
            $getAllVehicleRegistrationNumberResult = $modelObj->getAllVehicleRegistrationNumber();            
            while ($getAllVehicleRegistrationNumberRow = $getAllVehicleRegistrationNumberResult->fetch_assoc()) {
                array_push($allvehicleRegistrationNumbers, $getAllVehicleRegistrationNumberRow["vehicleRegistrationNumber"]);
            }
            try {
                if (
                    $vehicleManufacturerId != "" & $vehicleModelId != "" &
                    $vehicleColorId != "" & $classOfVehicleId != "" &
                    $vehicleRegistrationNumber != ""                    
                ) {
                    if (!preg_match($vehicleRegistrationNumberPattern, $vehicleRegistrationNumber)) {
                        $msg = "Invalid Vehicle Registration Number!";
                        $msg = base64_encode($msg);?>
                        <script>window.location="../view/add_vehicle.php?msgWarning=<?php echo $msg; ?>&moduleId=<?php echo $moduleId; ?>";</script>
<?php
                    } else if (preg_match($vehicleRegistrationNumberPattern, $vehicleRegistrationNumber)) {
                        if (!in_array($vehicleRegistrationNumber, $allvehicleRegistrationNumbers)) {  
                            $getSpecificVehicleModelByVehicleModelIdResult = $modelObj->getSpecificVehicleModelByVehicleModelId($vehicleModelId);
                            $getSpecificVehicleModelByVehicleModelIdRow = $getSpecificVehicleModelByVehicleModelIdResult->fetch_assoc();
                            $checkingVehicleManufacturerId = $getSpecificVehicleModelByVehicleModelIdRow["vehicleManufacturerId"];
    
                            if ($vehicleManufacturerId != $checkingVehicleManufacturerId) {                                
                                $msg = "Vehicle Model is Not Belong to Selected Vehicle Manufacturer!";
                                $msg = base64_encode($msg);?>
                                <script>window.location="../view/add_vehicle.php?msgWarning=<?php echo $msg; ?>&moduleId=<?php echo $moduleId; ?>";</script>
<?php
                            } else if ($vehicleManufacturerId == $checkingVehicleManufacturerId) {
                                $updateVehicleId = $modelObj->addNewVehicle(
                                    $vehicleManufacturerId,
                                    $vehicleModelId,

                                    $vehicleColorId,
                                    $classOfVehicleId,

                                    $vehicleRegistrationNumber,
                                    $vehicleImageEdit
                                );
                                $msg = "New Vehicle was Successfully Added!";
                                $msg = base64_encode($msg);?>
                                <script>window.location="../view/view_specific_vehicle.php?msgSuccess=<?php echo $msg; ?>&updateVehicleId=<?php echo $updateVehicleId; ?>&moduleId=<?php echo $moduleId; ?>";</script>
                                <!-- <script>window.location="../view/add_vehicle.php?msgWarning=<?php echo $msg; ?>&moduleId=<?php echo $moduleId; ?>";</script> -->
<?php
                            }
                        } else if (in_array($vehicleRegistrationNumber, $allvehicleRegistrationNumbers)) { 
                            $msg = "$vehicleRegistrationNumber is Already Used!";
                            $msg = base64_encode($msg);?>
                            <script>window.location="../view/add_vehicle.php?msgWarning=<?php echo $msg; ?>&moduleId=<?php echo $moduleId; ?>";</script>
<?php
                        }
                    }
