        // 1) Updae Specific Vehicle Overview
        case "updateSpecificVehicleOverview":    
            $vehicleStatus = $_POST["vehicleStatus"];

            $vehicleManufacturerId = $_POST["vehicleManufacturerId"];
            $vehicleModelId = $_POST["vehicleModelId"];

            $vehicleColorId = $_POST["vehicleColorId"];
            $classOfVehicleId = $_POST["classOfVehicleId"];

            $vehicleRegistrationNumber = $_POST["vehicleRegistrationNumber"];
            $vehicleImage = $_FILES["vehicleImage"];

            $vehicleCurrentStatusId = $_POST["vehicleCurrentStatusId"];

            $moduleId = $_POST["moduleId"];
            $updateVehicleId = $_POST["updateVehicleId"];

            $vehicleRegistrationNumberPattern = "/^[A-Z]{1,2}\s[A-Z]{1,3}\-[0-9]{4}(?<! 0{4})$/";

            $vehicleImageEdit = "";  
            if($vehicleImage["name"] != ""){
                $vehicleImageEdit = $vehicleImage["name"];
                $path = "../images/vehicle_images/".$vehicleImageEdit;
                move_uploaded_file($vehicleImage["tmp_name"], $path);                                       
            }

            $allvehicleRegistrationNumbers = array();
            $getAllVehicleRegistrationNumberResult = $modelObj->getAllVehicleRegistrationNumber();            
            while ($getAllVehicleRegistrationNumberRow = $getAllVehicleRegistrationNumberResult->fetch_assoc()) {
                array_push($allvehicleRegistrationNumbers, $getAllVehicleRegistrationNumberRow["vehicleRegistrationNumber"]);
            }
            try {
                if ($vehicleRegistrationNumber != "") {
                    if (!preg_match($vehicleRegistrationNumberPattern, $vehicleRegistrationNumber)) {
                        $msg = "Invalid Vehicle Registration Number!";
                        $msg = base64_encode($msg);?>
                        <script>window.location="../view/update_specific_vehicle.php?msgWarning=<?php echo $msg; ?>&updateVehicleId=<?php echo $updateVehicleId; ?>&moduleId=<?php echo $moduleId; ?>";</script>
<?php
