            $inventorySectionsProductsCapacityPattern = "/^[0-9]+$/";

            try { 
                $getSpecificInventorySectionSpecificProductResult = $modelObj->getSpecificInventorySectionSpecificProduct($productId, $updateWarehouseId, $updateWarehouseSectionId);
                $getSpecificInventorySectionSpecificProductRow = $getSpecificInventorySectionSpecificProductResult->fetch_assoc();

                $inventorySectionsProductsAvailability = $getSpecificInventorySectionSpecificProductRow["inventorySectionsProductsAvailability"];
                if (
                    $inventorySectionsProductsCapacity != ""
                ) {
                    if ($inventorySectionsProductsCapacity >= $inventorySectionsProductsAvailability) {                    
                        if (preg_match($inventorySectionsProductsCapacityPattern, $inventorySectionsProductsCapacity)) {
