            $financeTypeId = 1;
            $processStatusId = 1;
            
            $updateWarehouseId = $_POST["updateWarehouseId"];
            $updateWarehouseSectionId = $_POST["updateWarehouseSectionId"];
            $updateProductId = $_POST["updateProductId"];
            $requestProductAmount = $_POST["requestProductAmount"];
            $productSellingPrice = $_POST["productSellingPrice"];

            $moduleId = $_POST["moduleId"];
            
            $getSpecificClientAvailbaleInventorySectionProductsByProductIdResult = $modelObj->getSpecificClientAvailbaleInventorySectionProductsByProductId($updateProductId);
            $getSpecificClientAvailbaleInventorySectionProductsByProductIdRow = $getSpecificClientAvailbaleInventorySectionProductsByProductIdResult->fetch_assoc(); 

            $inventorySectionsProductsAvailability = $getSpecificClientAvailbaleInventorySectionProductsByProductIdRow["inventorySectionsProductsAvailability"];
            $inventorySectionsProductsReserved = $getSpecificClientAvailbaleInventorySectionProductsByProductIdRow["inventorySectionsProductsReserved"];

            $accessibleProductAmount = $inventorySectionsProductsAvailability - $inventorySectionsProductsReserved;
            $newInventorySectionsProductsReserved = $inventorySectionsProductsReserved + $requestProductAmount;
                        
            try {
                if (
                    $accessibleProductAmount >= $requestProductAmount
                ) {
                    $timezone = new DateTimeZone('Asia/Colombo');
                    $datetime = new DateTime('now', $timezone);
                    $currentDate  = $datetime->format('Y:m:d');  
                    $currentTime  = $datetime->format('h:i:s A');
                    $financeId = $modelObj->addFinanceId(
                        $financeTypeId,
                        $currentDate,
                        $currentTime
                    );
                    $clientRequestId = $modelObj->addClientRequest(
                        $clientUserId, 
                        $clientServiceId, 
                        $processStatusId,
                        $financeId, 
                        $financeTypeId, 
                        $currentDate, 
                        $currentTime
                    );
                    $modelObj->addProductPurchasingRequest(
                        $clientRequestId, 
                        $updateWarehouseId, 
                        $updateWarehouseSectionId, 
                        $updateProductId, 
                        $requestProductAmount, 
                        $productSellingPrice, 
                        $currentDate, 
                        $currentTime
                    );
                    $modelObj->updateSpecificInventorySectionProductReservedAmountAndAvailabilityBywarehouseIdwarehouseSectionIdproductId(
                        $newInventorySectionsProductsReserved, 
                        $inventorySectionsProductsAvailability,
                        $updateWarehouseId,
                        $updateWarehouseSectionId,
                        $updateProductId
                    );
                    $msg = "Your Product Purchasing was Successfully Added!";
                    $msg = base64_encode($msg); ?>
                    <script>window.location = "../view/view_your_specific_available_client_request.php?msgSuccess=<?php echo $msg; ?>&clientServiceId=<?php echo $clientServiceId; ?>&clientRequestId=<?php echo $clientRequestId; ?>&moduleId=<?php echo $moduleId; ?>";</script>                     
<?php
                } else if (
