            $transactionAmount = $_POST["transactionAmount"];
            $functionURL1 = $_POST["functionURL1"];
            $moduleId = $_POST["moduleId"];

            $transactionAmountPattern = "/^[0-9]+$/"; 

            try {
                if (
                    $transactionAmount != ""
                ) {
                    if (
                        preg_match($transactionAmountPattern, $transactionAmount)
                    ) {
                        $getSpecificBudgetBybudgetIdValueGettingResult = $modelObj->getSpecificBudgetBybudgetId($budgetIdGetting);
                        $getSpecificBudgetBybudgetIdValueGettingRow = $getSpecificBudgetBybudgetIdValueGettingResult->fetch_assoc();
                        
                        $currentGettingBudgetPrice = $getSpecificBudgetBybudgetIdValueGettingRow["budgetPrice"];

                        if ($currentGettingBudgetPrice >= $transactionAmount) {
                            $newGettingBudgetPrice = $currentGettingBudgetPrice - $transactionAmount;


                            $modelObj->updateSpecificBudgetBybudgetId($newGettingBudgetPrice, $budgetIdGetting);

                            $getSpecificBudgetBybudgetIdValueAddingResult = $modelObj->getSpecificBudgetBybudgetId($budgetIdAdding);
                            $getSpecificBudgetBybudgetIdValueAddingRow = $getSpecificBudgetBybudgetIdValueAddingResult->fetch_assoc();

                            $currentAddingBudgetPrice = $getSpecificBudgetBybudgetIdValueAddingRow["budgetPrice"];

                            $newAddingBudgetPrice = $currentAddingBudgetPrice + $transactionAmount;

                            $modelObj->updateSpecificBudgetBybudgetId($newAddingBudgetPrice, $budgetIdAdding);

                            $msg = "Transaction Successfully Processed!";
                            $msg = base64_encode($msg); ?>
                            <script>window.location = "../view/<?php echo $functionURL1; ?>msgSuccess=<?php echo $msg; ?>&moduleId=<?php echo $moduleId; ?>";</script> 
<?php

