        case "addNewFuelStation":
            $fuelStationName = $_POST["fuelStationName"];

            $moduleId = $_POST["moduleId"];

            $fuelStationNamePattern = "/^[a-zA-Z\s\)\(&]+$/";    
        
            $allfuelStationName = array();
            $getAllFuelStationsResult = $modelObj->getAllFuelStations();
            while ($getAllFuelStationsRow = $getAllFuelStationsResult->fetch_assoc()){
                array_push($allfuelStationName, $getAllFuelStationsRow["fuelStationName"]);
            }
            try {            
                if (
                    $fuelStationName != ""
                ) {                  
                    if (preg_match($fuelStationNamePattern, $fuelStationName)) {  
                        if (!in_array($fuelStationName, $allfuelStationName)) {
                            $modelObj->addNewFuelStation(
                                $fuelStationName
                            );
                            $msg = "Fuel Station Successfully Added!";
