<?php
                        }
                    } else {
                        $msg = "Invalid Data Entry!";
                        $msg = base64_encode($msg); ?>
                        <script>window.location = "../view/add_fuel_station.php?msgWarning=<?php echo $msg; ?>&moduleId=<?php echo $moduleId; ?>";</script>
<?php 
                    }
                    break;
                } else {
